using System;using System.Collections.Generic;using System.IO;using UnityEngine;
namespace RmlUnity {
 internal sealed class Match3ThreadCpuWindows {
  [Serializable] internal sealed class Window {
   public string phase;public bool valid,focusBegin,focusEnd;public int frames,firstFrame,lastFrame,deltaStart,deltaCount,deltaDropped,focusChanges,sampleFirstFrame=-1,sampleLastFrame=-1,deltaUsedCount;public bool deltaValid;public long cpuNs=-1,wallNs=-1,endpointBracketNs;public long borrowedActiveFrames;public long nativeFinalActiveFrames,nativeFinalReady,nativeFinalFallback,nativeFinalBytes;public long nativeCopyBytes,nativeFullBytes,nativePossibleBytes,nativeDeltaCopies;public long nativePrepares,nativeBuilds,nativeActiveFrames,nativePeakBytes,nativeStagingPeakBytes;public long commands,geometryCopies,batchBuilds,parameterDraws,snapshotHits,snapshotPayloadReads,snapshotDecodedCommands;public double deltaP50Ms=-1,deltaP95Ms=-1,deltaP99Ms=-1;public long tickBegin,tickEnd;public string utcBegin,utcEnd;
  }
  [Serializable] sealed class Report {public string schema="own Main user+kernel CPU; monotonic wall; not Render/GPU";public string workScope="LateUpdate samples: first/last endpoint frames bound CPU; work counters include begin Update and exclude end Update, not exact CPU interval";public string deltaScope="unscaledDeltaTime previous frame-start interval; 8 samples trimmed at each end, not CPU or presentation latency";public bool minimal;public int owner;public long clockResolutionNs;public Window[] windows;}
  readonly MacThreadCpuClock clock=new MacThreadCpuClock();readonly List<Window> windows=new List<Window>(4);readonly float[] deltas=new float[200000];int deltaAt;Window current;MacThreadCpuClock.Stamp start;bool read;internal bool Available=>clock.Available;
  internal void Phase(string phase){if(current!=null){read=clock.TryRead(out var end)&&read;current.valid=read&&MacThreadCpuClock.TryDelta(start,end,out current.cpuNs,out current.wallNs);if(!current.valid)current.cpuNs=current.wallNs=-1;current.endpointBracketNs=start.bracketNs+end.bracketNs;current.lastFrame=Time.frameCount;current.tickEnd=Match3MotionClock.Ticks;current.focusEnd=Application.isFocused;current.utcEnd=DateTime.UtcNow.ToString("O");windows.Add(current);current=null;}
   if(phase!=null){var next=new Window{phase=phase,firstFrame=Time.frameCount,deltaStart=deltaAt,focusBegin=Application.isFocused,tickBegin=Match3MotionClock.Ticks,utcBegin=DateTime.UtcNow.ToString("O")};read=clock.TryRead(out start);current=next;}
  }
  internal void FocusChanged(){if(current!=null)current.focusChanges++;}
  internal void Frame(float delta,RmlUnityHost host){if(current==null)return;current.frames++;if(current.sampleFirstFrame<0)current.sampleFirstFrame=Time.frameCount;current.sampleLastFrame=Time.frameCount;if(deltaAt<deltas.Length){deltas[deltaAt++]=delta;current.deltaCount++;}else current.deltaDropped++;if(host){if(host.BorrowedNativeFrameActive)current.borrowedActiveFrames++;if(host.NativeFinalFrameActive)current.nativeFinalActiveFrames++;current.nativeFinalReady+=host.NativeFinalFrameReady;current.nativeFinalFallback+=host.NativeFinalFrameFallback;current.nativeFinalBytes+=host.NativeFinalFrameBytes;current.nativeCopyBytes+=host.NativePayloadCopyBytes;current.nativeFullBytes+=host.NativePayloadFullBytes;current.nativePossibleBytes+=host.NativePayloadPossibleBytes;current.nativeDeltaCopies+=host.NativePayloadDeltaCopies;current.nativePrepares+=host.NativePreparedCalls;current.nativeBuilds+=host.NativePreparedBuilds;if(host.NativePreparedActive)current.nativeActiveFrames++;current.nativePeakBytes=Math.Max(current.nativePeakBytes,host.NativePreparedRetainedBytes);current.nativeStagingPeakBytes=Math.Max(current.nativeStagingPeakBytes,host.NativePreparedStagingBytes);current.snapshotHits+=host.ParameterFrameSnapshotHits;current.snapshotPayloadReads+=host.ParameterFramePayloadReads;current.snapshotDecodedCommands+=host.ParameterFrameDecodedCommands;current.commands+=host.DrawCommands;current.geometryCopies+=host.ParameterGeometryCopyCalls;current.batchBuilds+=host.ParameterBatchBuilds;current.parameterDraws+=host.ParameterDraws;}else current.snapshotHits=current.snapshotPayloadReads=current.snapshotDecodedCommands=current.commands=current.geometryCopies=current.batchBuilds=current.parameterDraws=-1;}
  static double Q(float[] xs,double p){double f=(xs.Length-1)*p;int i=(int)f;return xs[i]+(xs[Math.Min(i+1,xs.Length-1)]-xs[i])*(f-i);}
  static void FinishDistribution(Window w,float[] data){w.deltaP50Ms=w.deltaP95Ms=w.deltaP99Ms=-1;w.deltaValid=false;w.deltaUsedCount=0;if(w.deltaDropped!=0||w.deltaCount<=16)return;var a=new float[w.deltaCount-16];Array.Copy(data,w.deltaStart+8,a,0,a.Length);Array.Sort(a);w.deltaP50Ms=Q(a,.5);w.deltaP95Ms=Q(a,.95);w.deltaP99Ms=Q(a,.99);w.deltaUsedCount=a.Length;w.deltaValid=true;}
  internal static void TestDistributions(){var data=new float[32];for(int i=0;i<data.Length;i++)data[i]=i;foreach(int n in new[]{0,8,16}){var w=new Window{deltaCount=n};FinishDistribution(w,data);if(w.deltaValid||w.deltaP50Ms!=-1||w.deltaP95Ms!=-1||w.deltaP99Ms!=-1||w.deltaUsedCount!=0)throw new Exception("THREAD_CPU_FAIL short distribution");}var dropped=new Window{deltaCount=32,deltaDropped=1};FinishDistribution(dropped,data);if(dropped.deltaValid||dropped.deltaP50Ms!=-1)throw new Exception("THREAD_CPU_FAIL dropped distribution");var good=new Window{deltaCount=32};FinishDistribution(good,data);if(!good.deltaValid||good.deltaUsedCount!=16||good.deltaP50Ms!=15.5)throw new Exception("THREAD_CPU_FAIL retained distribution");}
  internal void Save(string path,bool minimal){if(current!=null)throw new InvalidOperationException("Measured window must end before serialization");foreach(var w in windows)FinishDistribution(w,deltas);
   File.WriteAllText(path,JsonUtility.ToJson(new Report{minimal=minimal,owner=clock.Owner,clockResolutionNs=clock.ResolutionNs,windows=windows.ToArray()},true));
  }
 }
}
